-- T-039 núcleo / MVP-0 "publicar agora": a publication may carry free text written by the owner instead
-- of a draft version. Additive only: existing rows keep draft_id/draft_version_id and body stays NULL.

-- AlterTable (generated by `prisma migrate diff`)
ALTER TABLE "publications" ADD COLUMN     "body" TEXT,
ALTER COLUMN "draft_id" DROP NOT NULL,
ALTER COLUMN "draft_version_id" DROP NOT NULL;

-- CHECK constraints (hand-written)
-- Exactly one origin: a draft version (draft_id + draft_version_id) or the manual text (body).
ALTER TABLE "publications" ADD CONSTRAINT "publications_origin_check"
  CHECK (("draft_id" IS NULL) = ("draft_version_id" IS NULL)
     AND ("draft_id" IS NULL) = ("body" IS NOT NULL));
-- Manual text follows the LinkedIn commentary bound and is only published now (never scheduled).
ALTER TABLE "publications" ADD CONSTRAINT "publications_manual_body_check"
  CHECK ("body" IS NULL OR (char_length("body") BETWEEN 1 AND 3000 AND "schedule_id" IS NULL));
